package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;

/**
 * The audit line of a claim change: amount as shown (two decimals), date as yyyy-mm-dd, then the
 * claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    /** CLAIM_ADDED: the line, then ref=<reference> when the claim carries one, then tags=<sorted, comma separated> when it has any. */
    static String added(String user, Person person, Claim claim) {
        return line("CLAIM_ADDED", user, person, claim, claim.getNumber()) + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags());
    }

    static String line(String event, String user, Person person, Claim claim, String number) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date() + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            Claims claims, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = null;
        try {
            claim = claims.find(sheetId, Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (claim == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.plugin.variable.Val;

public class AuditClaimEdited {
    public void audit(@Val ValidClaim request, @Val Claim claim, People people, Audit audit, @Val RollupFigures before, Rollup rollup) {
        audit.recordOnCommit(ClaimAudit.line("CLAIM_EDITED", request.user(),
                people.find(claim.getSheetId(), claim.getPersonId()), claim, claim.getNumber()));
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
